/**
 * 从 URL 中解析外链参入的登录 token（`?token=xxx` 或 `#/...?token=xxx`）。
 * 规则：trim 后非空；decodeURIComponent 容错（解码失败用原值）；重复 token 取第一个；缺失/空串返回 null。
 * 同时兼容 uni-app H5 hash 路由（query 常挂在 hash 段的 ? 之后）。
 */
export function peekUrlToken(): string | null {
  if (typeof window === 'undefined' || !window.location) return null
  const { search, hash } = window.location
  const sources: string[] = [search ?? '']
  const hashQueryIndex = (hash ?? '').indexOf('?')
  if (hashQueryIndex >= 0) sources.push(hash!.slice(hashQueryIndex))
  for (const source of sources) {
    if (!source) continue
    const params = new URLSearchParams(source)
    const raw = params.get('token')
    if (raw == null) continue
    let value = raw
    try { value = decodeURIComponent(raw) } catch { /* 解码失败保留原值 */ }
    value = value.trim()
    if (value) return value
  }
  return null
}

/**
 * 从当前 URL 移除 token 参数（search 与 hash query 都处理），保留其它查询参数、hash 路由路径与 history.state。
 * 用 history.replaceState 原地替换，不新增历史记录，也不触发路由跳转。
 */
export function stripUrlToken(): void {
  if (typeof window === 'undefined' || !window.history || !window.location) return
  const { origin, pathname, search, hash } = window.location
  const strip = (qs: string): string => {
    if (!qs) return qs
    const params = new URLSearchParams(qs)
    if (!params.has('token')) return qs
    params.delete('token')
    const rest = params.toString()
    return rest ? `?${rest}` : ''
  }
  const nextSearch = strip(search ?? '')
  const hashQueryIndex = (hash ?? '').indexOf('?')
  const nextHash = hashQueryIndex >= 0
    ? hash!.slice(0, hashQueryIndex) + strip(hash!.slice(hashQueryIndex))
    : (hash ?? '')
  if (nextSearch === (search ?? '') && nextHash === (hash ?? '')) return
  const nextUrl = `${origin}${pathname}${nextSearch}${nextHash}`
  try { window.history.replaceState(window.history.state ?? {}, '', nextUrl) } catch { /* 忽略环境限制 */ }
}

