  // happy-dom 下用 setURL 改写当前文档地址（replaceState 跨源会抛 SecurityError）
  const hd = (window as unknown as { happyDOM?: { setURL: (u: string) => void } }).happyDOM
  if (hd?.setURL) hd.setURL(url)
  else window.history.replaceState({}, '', url)
}

